1	package stowage
2	
3	import (
4		"sort"
5		"strconv"
6		"strings"
7	)
8	
9	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
10	//
11	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
12	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
13	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
14	// 可以修正后重试。内容比较按编号去空白后的原始字节进行：登记处能
15	// 区分的编号（包括含无效 UTF-8 字节的编号）在内容判断中同样区分。
16	// 卸下操作忽略目标值，其目标不参与内容比较；装载与移动的目标舱位
17	// 参与比较。
18	//
19	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
20	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
21	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
22	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
23	// 范围也会被拒绝。
24	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
25		r.mu.Lock()
26		defer r.mu.Unlock()
27	
28		aid := strings.TrimSpace(adjustmentID)
29		if aid == "" {
30			return nil, fail(ErrInvalidID, "", "调整编号为空")
31		}
32	
33		// f 构造带调整编号的错误。
34		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
35			e := fail(kind, id, format, args...)
36			e.AdjustmentID = aid
37			return e
38		}
39	
40		// 幂等：编号已成功使用过。
41		if saved, ok := r.adjustments[aid]; ok {
42			if r.contents[aid] == canonicalKey(ops) {
43				return cloneResult(saved), nil
44			}
45			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
46		}
47	
48		if len(ops) == 0 {
49			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
50		}
51	
52		vops, final, affected, err := r.prepareOps(ops, f)
53		if err != nil {
54			return nil, err
55		}
56	
57		// 按最终配载校验承重与混装限制，返回第一个问题即拒绝整次调整；
58		// 拒绝原因到结构化错误的转换与 AmendCargo 共用。
59		if rej := r.firstRejection(final); rej != nil {
60			return nil, rejectionError(rej, f)
61		}
62	
63		// 全部合法，正式生效。先计算受影响舱位调整前后的重量；前后配载都
64		// 经过重量校验（原配载由历次成功操作累积而成，最终配载刚通过检查），
65		// 合计必然可以用 int64 表示。
66		cargoChanges := make([]CargoChange, 0, len(vops))
67		compChanges := make([]CompartmentChange, 0, len(affected))
68		for id := range affected {
69			before, _ := weightTotal(r.compartments[id].cargo)
70			after, _ := weightTotal(final[id])
71			compChanges = append(compChanges, CompartmentChange{
72				CompartmentID: id,
73				WeightBefore:  before,
74				WeightAfter:   after,
75			})
76		}
77		sort.Slice(compChanges, func(i, j int) bool {
78			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
79		})
80	
81		for _, v := range vops {
82			c := v.cargo
83			from := c.compartmentID
84			var to string
85			switch v.op.Kind {
86			case OpLoad:
87				r.compartments[v.target.id].cargo[c.id] = c
88				c.compartmentID = v.target.id
89				to = v.target.id
90			case OpUnload:
91				delete(r.compartments[from].cargo, c.id)
92				c.compartmentID = ""
93			case OpMove:
94				delete(r.compartments[from].cargo, c.id)
95				r.compartments[v.target.id].cargo[c.id] = c
96				c.compartmentID = v.target.id
97				to = v.target.id
98			}
99			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
100		}
101		sort.Slice(cargoChanges, func(i, j int) bool {
102			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
103		})
104	
105		result := &AdjustmentResult{
106			ID:                 aid,
107			CargoChanges:       cargoChanges,
108			CompartmentChanges: compChanges,
109		}
110		r.adjustments[aid] = result
111		r.contents[aid] = canonicalKey(ops)
112		return cloneResult(result), nil
113	}
114	
115	// validOp 是一条通过逐条校验的操作，附带其涉及的内部记录。
116	type validOp struct {
117		op     Op
118		cargo  *cargo
119		target *compartment // 装载/移动的目标舱位；卸下时为 nil
120	}
121	
122	// prepareOps 逐条校验操作并在模拟配载上应用全部操作。
123	// 调用方必须持有 r.mu。任一操作不合法时返回该错误，最终配载与受影响
124	// 舱位集合只在全部操作合法时返回。受影响舱位包括各操作的原舱位与
125	// 目标舱位（交换中的两个舱位都会纳入）。
126	func (r *Registry) prepareOps(
127		ops []Op,
128		failf func(kind ErrorKind, id string, format string, args ...any) *Error,
129	) (vops []validOp, final map[string]map[string]*cargo, affected map[string]bool, err error) {
130		seen := make(map[string]bool)
131		vops = make([]validOp, 0, len(ops))
132		affected = make(map[string]bool)
133	
134		for _, op := range ops {
135			cid := strings.TrimSpace(op.CargoID)
136			if cid == "" {
137				return nil, nil, nil, failf(ErrInvalidID, "", "货物编号为空")
138			}
139			c, ok := r.cargos[cid]
140			if !ok {
141				return nil, nil, nil, failf(ErrNotFound, cid, "货物 %s 不存在", cid)
142			}
143			if seen[cid] {
144				return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
145			}
146			seen[cid] = true
147	
148			switch op.Kind {
149			case OpLoad:
150				if c.compartmentID != "" {
151					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
152				}
153				tid := strings.TrimSpace(op.Target)
154				if tid == "" {
155					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
156				}
157				t, ok := r.compartments[tid]
158				if !ok {
159					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
160				}
161				vops = append(vops, validOp{op, c, t})
162				affected[t.id] = true
163			case OpUnload:
164				if c.compartmentID == "" {
165					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
166				}
167				vops = append(vops, validOp{op, c, nil})
168				affected[c.compartmentID] = true
169			case OpMove:
170				if c.compartmentID == "" {
171					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
172				}
173				tid := strings.TrimSpace(op.Target)
174				if tid == "" {
175					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
176				}
177				t, ok := r.compartments[tid]
178				if !ok {
179					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
180				}
181				if t.id == c.compartmentID {
182					return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
183				}
184				vops = append(vops, validOp{op, c, t})
185				affected[c.compartmentID] = true
186				affected[t.id] = true
187			default:
188				return nil, nil, nil, failf(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
189			}
190		}
191	
192		// 在模拟配载上应用全部操作，判断以完成后的最终状态为准。
193		final = make(map[string]map[string]*cargo, len(r.compartments))
194		for id, comp := range r.compartments {
195			set := make(map[string]*cargo, len(comp.cargo))
196			for cid, c := range comp.cargo {
197				set[cid] = c
198			}
199			final[id] = set
200		}
201		for _, v := range vops {
202			switch v.op.Kind {
203			case OpLoad:
204				final[v.target.id][v.cargo.id] = v.cargo
205			case OpUnload:
206				delete(final[v.cargo.compartmentID], v.cargo.id)
207			case OpMove:
208				delete(final[v.cargo.compartmentID], v.cargo.id)
209				final[v.target.id][v.cargo.id] = v.cargo
210			}
211		}
212		return vops, final, affected, nil
213	}
214	
215	// evaluateFinal 按最终配载评估每个舱位的承重与混装限制，一个舱位可以
216	// 同时得到重量原因（超重或溢出）与混装原因。结果不保证顺序。
217	// 调用方必须持有 r.mu。
218	func (r *Registry) evaluateFinal(final map[string]map[string]*cargo) []*Rejection {
219		var rejs []*Rejection
220		for id, set := range final {
221			comp := r.compartments[id]
222	
223			// 重量原因：合计规则与快照共用同一入口；溢出优先，溢出时不提供
224			// 任何重量数值。
225			sum, ok := weightTotal(set)
226			var rej *Rejection
227			if !ok {
228				rej = &Rejection{
229					CompartmentID: id,
230					Kind:          ErrOverflow,
231					MaxWeight:     comp.maxWeight,
232				}
233			} else if sum > comp.maxWeight {
234				rej = &Rejection{
235					CompartmentID:   id,
236					Kind:            ErrOverweight,
237					MaxWeight:       comp.maxWeight,
238					UsedWeight:      sum,
239					RemainingWeight: comp.maxWeight - sum,
240					Overweight:      sum - comp.maxWeight,
241				}
242			}
243	
244			// 混装原因：不同目的地共舱时，列出全部不允许混装的货物。
245			destinations := make(map[string][]string)
246			destSet := make(map[string]bool)
247			var offenders []string
248			for _, c := range set {
249				destinations[c.destination] = append(destinations[c.destination], c.id)
250				destSet[c.destination] = true
251				if !c.allowMixed {
252					offenders = append(offenders, c.id)
253				}
254			}
255			if len(destSet) > 1 && len(offenders) > 0 {
256				dests := make([]MixedDestination, 0, len(destinations))
257				for dest, ids := range destinations {
258					sorted := append([]string(nil), ids...)
259					sort.Strings(sorted)
260					dests = append(dests, MixedDestination{Destination: dest, CargoIDs: sorted})
261				}
262				sort.Slice(dests, func(i, j int) bool {
263					return dests[i].Destination < dests[j].Destination
264				})
265				sort.Strings(offenders)
266				mr := &Rejection{
267					CompartmentID:  id,
268					Kind:           ErrMixedLoading,
269					MaxWeight:      comp.maxWeight,
270					Destinations:   dests,
271					OffendingCargo: offenders,
272				}
273				if rej != nil {
274					rejs = append(rejs, rej, mr)
275				} else {
276					rejs = append(rejs, mr)
277				}
278			} else if rej != nil {
279				rejs = append(rejs, rej)
280			}
281		}
282		return rejs
283	}
284	
285	// firstRejection 以与正式调整一致的顺序返回第一个拒绝原因；没有则 nil。
286	// 调用方必须持有 r.mu。
287	func (r *Registry) firstRejection(final map[string]map[string]*cargo) *Rejection {
288		rejs := r.evaluateFinal(final)
289		if len(rejs) == 0 {
290			return nil
291		}
292		sort.Slice(rejs, func(i, j int) bool {
293			if rejs[i].CompartmentID != rejs[j].CompartmentID {
294				return rejs[i].CompartmentID < rejs[j].CompartmentID
295			}
296			return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
297		})
298		return rejs[0]
299	}
300	
301	// rejKindOrder 规定同一舱位的拒绝原因次序：重量（超重/溢出）先于混装。
302	func rejKindOrder(k ErrorKind) int {
303		switch k {
304		case ErrOverflow, ErrOverweight:
305			return 0
306		default:
307			return 1
308		}
309	}
310	
311	// firstOffender 返回混装原因中编号最小的货物，用于错误说明。
312	func (x *Rejection) firstOffender() string {
313		if len(x.OffendingCargo) == 0 {
314			return ""
315		}
316		return x.OffendingCargo[0]
317	}
318	
319	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
320	// 即视为相同内容，排列顺序不影响判断。卸下操作忽略目标舱位（执行时
321	// 同样忽略），其目标值不影响内容判断；装载与移动的目标舱位参与比较。
322	// 编号按去掉首尾空白后的原始字节精确比较：任何字节差异都视为不同内容，
323	// 包含无效 UTF-8 字节的编号与包含 Unicode 替代字符 U+FFFD 的编号也不相同。
324	func canonicalKey(ops []Op) string {
325		sorted := make([]Op, len(ops))
326		for i, op := range ops {
327			target := strings.TrimSpace(op.Target)
328			if op.Kind == OpUnload {
329				target = ""
330			}
331			sorted[i] = Op{
332				Kind:    op.Kind,
333				CargoID: strings.TrimSpace(op.CargoID),
334				Target:  target,
335			}
336		}
337		sort.Slice(sorted, func(i, j int) bool {
338			if sorted[i].Kind != sorted[j].Kind {
339				return sorted[i].Kind < sorted[j].Kind
340			}
341			if sorted[i].CargoID != sorted[j].CargoID {
342				return sorted[i].CargoID < sorted[j].CargoID
343			}
344			return sorted[i].Target < sorted[j].Target
345		})
346		// 长度前缀编码保留原始字节，不做任何字符集层面的规整，
347		// 任意字节内容都不会因分隔符或转义而碰撞。
348		var b strings.Builder
349		for _, op := range sorted {
350			b.WriteString(strconv.Itoa(int(op.Kind)))
351			b.WriteByte('|')
352			writeRawField(&b, op.CargoID)
353			writeRawField(&b, op.Target)
354		}
355		return b.String()
356	}
357	
358	// writeRawField 以“长度:原始字节”的形式写入一个字段。
359	func writeRawField(b *strings.Builder, s string) {
360		b.WriteString(strconv.Itoa(len(s)))
361		b.WriteByte(':')
362		b.WriteString(s)
363	}
364

