547			t.Fatal(err)
548		}
549		if pv.Submittable {
550			t.Fatal("预览应判定不可提交")
551		}
552		got := make([][2]string, 0, len(pv.Rejections))
553		for _, x := range pv.Rejections {
554			got = append(got, [2]string{x.CompartmentID, x.Kind.String()})
555		}
556		want := [][2]string{
557			{"C1", "超重"},
558			{"C1", "混装冲突"},
559			{"C2", "超重"},
560		}
561		if !reflect.DeepEqual(got, want) {
562			t.Fatalf("Preview 应列全全部拒绝原因: %+v", got)
563		}
564		// Preview 给出全部受影响舱位的完整前后清单，这是 Adjust 的单条错误
565		// 不提供的信息。
566		if len(pv.Compartments) != 2 ||
567			pv.Compartments[0].ID != "C1" || pv.Compartments[1].ID != "C2" {
568			t.Fatalf("Preview 应列出两个受影响舱位: %+v", pv.Compartments)
